import sqlite3
import pandas as pd
import matplotlib.pyplot as plt


try:
    # Connecting to the database
    conn = sqlite3.connect("../db/lesson.db")


    # SQL query to calculate revenue generated by each employee
    query = """
        SELECT
            last_name,
            SUM(price * quantity) AS revenue
        FROM employees e
        JOIN orders o
            ON e.employee_id = o.employee_id
        JOIN line_items l
            ON o.order_id = l.order_id
        JOIN products p
            ON l.product_id = p.product_id
        GROUP BY e.employee_id;
    """


    # Loading the SQL query results into a Pandas DataFrame
    employee_results = pd.read_sql_query(
        query,
        conn
    )


    # Printing the DataFrame to verify the results
    print("Employee Revenue Results:")
    print(employee_results)


    # Creating a bar chart using Pandas
    employee_results.plot(
        kind="bar",
        x="last_name",
        y="revenue",
        color="steelblue",
        legend=False,
        figsize=(10, 6)
    )


    # Adding chart title and labels
    plt.title("Revenue Generated by Employee")
    plt.xlabel("Employee Last Name")
    plt.ylabel("Revenue ($)")

    # Improving layout
    plt.xticks(rotation=45)
    plt.tight_layout()

    # Displaying the chart
    plt.show()


except sqlite3.Error as error:
    print(f"SQLite error: {error}")


finally:
    if "conn" in locals():
        conn.close()
        print("Database connection closed.")